using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
class MapDisplay {
 static void Main(string[] a){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[3]);resolver.AddSearchDirectory(System.IO.Path.GetDirectoryName(a[1]));var asm=AssemblyDefinition.ReadAssembly(a[0],new ReaderParameters{AssemblyResolver=resolver});var helper=AssemblyDefinition.ReadAssembly(a[1]);var map=asm.MainModule.ImportReference(helper.MainModule.GetType("CW3Display").Methods.Single(m=>m.Name=="ForLabel"));var method=asm.MainModule.GetType("UILabel").Methods.Single(m=>m.Name=="ProcessText");var reads=method.Body.Instructions.Where(i=>i.OpCode==OpCodes.Ldfld&&((FieldReference)i.Operand).Name=="mText").ToArray();if(reads.Length!=9)throw new Exception("Unexpected mText reads: "+reads.Length);var il=method.Body.GetILProcessor();foreach(var i in reads.Skip(reads.Length-3)){var self=il.Create(OpCodes.Ldarg_0);il.InsertAfter(i,self);il.InsertAfter(self,il.Create(OpCodes.Call,map));}asm.Write(a[2]);Console.WriteLine("Mapped exactly three non-password display reads; raw fields/getters and selection values untouched.");}
}
